// English is a permanent product requirement. Original sources and personal
// records are preserved; this module projects older public reading metadata.
export const SITE_LANGUAGE='en';
export const containsVietnamese=value=>/[\u0102\u0103\u0110\u0111\u01a0\u01a1\u01af\u01b0\u1ea0-\u1eff]/u.test(String(value||''));
export const CASE_ENGLISH={
 'case-befa3d04':{title:'OMG 3Q: renewing a gaming community after nine years',summary:'VNGGames combined outfits inspired by Vietnamese culture, a 3H content approach, and livestreaming to connect players. The original case examines how a long-established brand turned its community heritage into a new experience.',question:'Which activities serve existing players and which reach new players? Distinguish the objectives and evaluation metrics for each group.'},
 'case-e6fd4dc3':{title:'Play Together: turning shared play into connection',summary:'The campaign used playing with friends to connect social content, livestreaming, in-person activities, and in-game experiences. The original case considers attracting new players, retaining current players, and reminding former players of the game.',question:'Which insight led to this strategic choice? What evidence would you use to assess its results?'},
 'case-f3252d60':{title:'VALORANT: Vietnamese identity at a regional tournament',summary:'Riot Games and VNGGames incorporated Vietnamese cultural elements into the VCT Pacific Stage 1 experience in Ho Chi Minh City. The source explores how the host location became part of the event’s brand story.',question:'How can an international event retain its brand identity while using local culture meaningfully rather than as decoration?'},
 'case-826a8cc6':{title:'Clorox: Clean is the beginning',summary:'Clorox extended its cleaning story to positive new beginnings in everyday life, drawing on a neuroscience-based argument. When reading the case, distinguish the brand message from scientific evidence and the conditions under which a claim applies.',question:'What evidence supports the brand promise? Which campaign results are self-reported, and what would require independent verification?'},
 'case-626a3cfe':{title:'NESCAFÉ Signature: Why not enjoy café-style coffee at home?',summary:'NESCAFÉ used the inconveniences of going to a café to introduce an at-home coffee experience. The source describes connections between usage occasions, outdoor advertising, and a partnership with Grab.',question:'How do the consumer insight, product benefit, and advertising context connect? What might limit a shift from café visits to coffee at home?'}
};
const LEGACY_STORY_ENGLISH={};
export function englishStory(story){
 if(!story)return story;const nonEnglish=containsVietnamese(story.title)||containsVietnamese(story.subtitle),known=LEGACY_STORY_ENGLISH[story.url];
 return {...story,...(nonEnglish?{originalTitle:story.originalTitle||story.title,originalSubtitle:story.originalSubtitle||story.subtitle,...(known||{title:'Saved source article · '+(story.publisher||'Publisher'),subtitle:'This saved article was published in another language. Open its original source for the full report; a verified English summary is not available.'})}:{}),topic:story.topic==='Thế giới'?'World':story.topic==='Kinh doanh'?'Business':story.topic,image:story.image?{...story.image,alt:nonEnglish?(known?.title||'Original source image from '+story.publisher):story.image.alt,credit:containsVietnamese(story.image.credit)?'Image from '+story.publisher:story.image.credit}:null,language:'en'};
}
export function englishCase(item){
 if(!item)return item;const nonEnglish=[item.title,item.summary,item.question].some(containsVietnamese),copy=nonEnglish?CASE_ENGLISH[item.id]:null;
 return {...item,...(nonEnglish?{originalTitle:item.originalTitle||item.title,originalSummary:item.originalSummary||item.summary,originalQuestion:item.originalQuestion||item.question}:{}),...(copy||{}),...(!copy&&nonEnglish?{title:'Source case study · '+(item.brand||item.publisher),summary:'Read this case at its original source. A verified English overview is not available yet.',question:'What are the context, strategic choices, evidence, and limitations in the original source?'}:{}),campaignPeriod:containsVietnamese(item.campaignPeriod)?(item.campaignPeriod==='09/2017 · case lịch sử'?'09/2017 · historical case':'Campaign context: see the original source'):item.campaignPeriod,image:item.image?{...item.image,alt:copy?.title||(containsVietnamese(item.image.alt)?'Original case-study source image':item.image.alt||item.title),credit:containsVietnamese(item.image.credit)?'Source image · '+item.publisher:item.image.credit}:null,language:'en'};
}
export function englishEdition(value){return {...value,language:'en',items:(value.items||[]).map(englishStory),caseStudies:(value.caseStudies||[]).map(englishCase)};}
